1	/**
2	 * Table Plugin
3	 *
4	 * Implements live preview for Markdown tables:
5	 * - Cursor outside table → render as HTML table
6	 * - Cursor inside table → show source, editable
7	 *
8	 * Uses StateField because block decorations must be provided via StateField
9	 */
10	
11	import { syntaxTree } from '@codemirror/language';
12	import { EditorState, Range, StateField } from '@codemirror/state';
13	import { Decoration, DecorationSet, EditorView } from '@codemirror/view';
14	import { shouldShowSource } from '../core/shouldShowSource';
15	import { mouseSelectingField } from '../core/mouseSelecting';
16	import { parseMarkdownTable } from '../utils/tableParser';
17	import { createTableWidget } from '../widgets/tableWidget';
18	
19	/**
20	 * Build table decorations
21	 */
22	function buildTableDecorations(state: EditorState): DecorationSet {
23	  const decorations: Range<Decoration>[] = [];
24	  const isDrag = state.field(mouseSelectingField, false);
25	
26	  syntaxTree(state).iterate({
27	    enter: (node) => {
28	      if (node.name === 'Table') {
29	        const tableSource = state.doc.sliceString(node.from, node.to);
30	        const tableData = parseMarkdownTable(tableSource);
31	
32	        // Don't render invalid tables
33	        if (!tableData) return;
34	
35	        const isTouched = shouldShowSource(state, node.from, node.to);
36	
37	        if (!isTouched && !isDrag) {
38	          // Render mode: show HTML table
39	          const widget = createTableWidget(tableData);
40	          decorations.push(
41	            Decoration.replace({ widget, block: true }).range(node.from, node.to)
42	          );
43	        } else {
44	          // Edit mode: add background to each table line
45	          for (let pos = node.from; pos <= node.to; ) {
46	            const line = state.doc.lineAt(pos);
47	            decorations.push(
48	              Decoration.line({ class: 'cm-table-source' }).range(line.from)
49	            );
50	            pos = line.to + 1;
51	          }
52	        }
53	      }
54	    },
55	  });
56	
57	  return Decoration.set(decorations.sort((a, b) => a.from - b.from), true);
58	}
59	
60	/**
61	 * Table StateField
62	 *
63	 * Manages table decoration state
64	 */
65	export const tableField = StateField.define<DecorationSet>({
66	  create(state) {
67	    return buildTableDecorations(state);
68	  },
69	
70	  update(deco, tr) {
71	    // Rebuild on document or config change
72	    if (tr.docChanged || tr.reconfigured) {
73	      return buildTableDecorations(tr.state);
74	    }
75	
76	    // Rebuild on drag state change
77	    const isDragging = tr.state.field(mouseSelectingField, false);
78	    const wasDragging = tr.startState.field(mouseSelectingField, false);
79	
80	    if (wasDragging && !isDragging) {
81	      return buildTableDecorations(tr.state);
82	    }
83	
84	    // Keep unchanged during drag
85	    if (isDragging) {
86	      return deco;
87	    }
88	
89	    // Rebuild on selection change
90	    if (tr.selection) {
91	      return buildTableDecorations(tr.state);
92	    }
93	
94	    return deco;
95	  },
96	
97	  provide: (f) => EditorView.decorations.from(f),
98	});
