1	/**
2	 * Editable Table Plugin
3	 *
4	 * Advanced Live Preview for Markdown tables:
5	 * - Always render table in Live mode
6	 * - Toggle source mode via explicit button
7	 * - Editable headers and cells in Live mode
8	 */
9	
10	import { syntaxTree } from '@codemirror/language';
11	import { EditorState, Extension, Range, StateField } from '@codemirror/state';
12	import { Decoration, DecorationSet, EditorView } from '@codemirror/view';
13	import { parseMarkdownTable } from '../utils/tableParser';
14	import {
15	  createTableEditorWidget,
16	  createTableSourceToggleWidget,
17	} from '../widgets/tableEditorWidget';
18	import { setTableSourceMode, TableSourceModeToggle } from './tableEditorEffects';
19	
20	interface TableSourceRange {
21	  from: number;
22	  to: number;
23	}
24	
25	function rangesOverlap(a: TableSourceRange, b: TableSourceRange): boolean {
26	  return a.from <= b.to && a.to >= b.from;
27	}
28	
29	function removeRange(ranges: TableSourceRange[], target: TableSourceRange): TableSourceRange[] {
30	  return ranges.filter((range) => !rangesOverlap(range, target));
31	}
32	
33	function addRange(ranges: TableSourceRange[], next: TableSourceRange): TableSourceRange[] {
34	  if (ranges.some((range) => rangesOverlap(range, next))) {
35	    return ranges;
36	  }
37	  return [...ranges, next];
38	}
39	
40	function isTableInSourceMode(
41	  ranges: TableSourceRange[],
42	  from: number,
43	  to: number
44	): boolean {
45	  return ranges.some((range) => range.from <= to && range.to >= from);
46	}
47	
48	const tableSourceModeField = StateField.define<TableSourceRange[]>({
49	  create: () => [],
50	  update(ranges, tr) {
51	    let next = ranges.map((range) => ({
52	      from: tr.changes.mapPos(range.from, 1),
53	      to: tr.changes.mapPos(range.to, -1),
54	    }));
55	
56	    for (const effect of tr.effects) {
57	      if (!effect.is(setTableSourceMode)) continue;
58	      const { from, to, showSource } = effect.value as TableSourceModeToggle;
59	      const mapped = {
60	        from: tr.changes.mapPos(from, 1),
61	        to: tr.changes.mapPos(to, -1),
62	      };
63	      next = showSource ? addRange(next, mapped) : removeRange(next, mapped);
64	    }
65	
66	    return next;
67	  },
68	});
69	
70	function buildTableDecorations(state: EditorState): DecorationSet {
71	  const decorations: Range<Decoration>[] = [];
72	  const sourceRanges = state.field(tableSourceModeField);
73	
74	  syntaxTree(state).iterate({
75	    enter: (node) => {
76	      if (node.name !== 'Table') return;
77	
78	      const tableSource = state.doc.sliceString(node.from, node.to);
79	      const tableData = parseMarkdownTable(tableSource);
80	
81	      if (!tableData) return;
82	
83	      const showSource = isTableInSourceMode(sourceRanges, node.from, node.to);
84	
85	      if (!showSource) {
86	        const widget = createTableEditorWidget(tableData, node.from, node.to);
87	        decorations.push(
88	          Decoration.replace({ widget, block: true }).range(node.from, node.to)
89	        );
90	        return;
91	      }
92	
93	      const toggleWidget = createTableSourceToggleWidget(node.from, node.to);
94	      decorations.push(
95	        Decoration.widget({ widget: toggleWidget, block: true }).range(node.from)
96	      );
97	
98	      for (let pos = node.from; pos <= node.to; ) {
99	        const line = state.doc.lineAt(pos);
100	        decorations.push(
101	          Decoration.line({ class: 'cm-table-source' }).range(line.from)
102	        );
103	        pos = line.to + 1;
104	      }
105	    },
106	  });
107	
108	  return Decoration.set(decorations.sort((a, b) => a.from - b.from), true);
109	}
110	
111	export const tableEditorField = StateField.define<DecorationSet>({
112	  create(state) {
113	    return buildTableDecorations(state);
114	  },
115	
116	  update(deco, tr) {
117	    if (
118	      tr.docChanged ||
119	      tr.reconfigured ||
120	      tr.effects.some((effect) => effect.is(setTableSourceMode))
121	    ) {
122	      return buildTableDecorations(tr.state);
123	    }
124	
125	    return deco;
126	  },
127	
128	  provide: (f) => EditorView.decorations.from(f),
129	});
130	
131	export function tableEditorPlugin(): Extension {
132	  return [tableSourceModeField, tableEditorField];
133	}
134	
135	export { setTableSourceMode };
