1	/**
2	 * Table Widget
3	 *
4	 * Renders Markdown table as HTML table
5	 */
6	
7	import { WidgetType } from '@codemirror/view';
8	import { TableData } from '../utils/tableParser';
9	import { renderInlineMarkdown } from '../utils/inlineMarkdown';
10	
11	/**
12	 * Table Widget class
13	 */
14	export class TableWidget extends WidgetType {
15	  constructor(readonly data: TableData) {
16	    super();
17	  }
18	
19	  /**
20	   * Check if two widgets are equal
21	   */
22	  eq(other: TableWidget): boolean {
23	    if (this.data.headers.length !== other.data.headers.length) return false;
24	    if (this.data.rows.length !== other.data.rows.length) return false;
25	
26	    // Compare headers
27	    for (let i = 0; i < this.data.headers.length; i++) {
28	      if (this.data.headers[i] !== other.data.headers[i]) return false;
29	      if (this.data.alignments[i] !== other.data.alignments[i]) return false;
30	    }
31	
32	    // Compare data rows
33	    for (let i = 0; i < this.data.rows.length; i++) {
34	      for (let j = 0; j < this.data.headers.length; j++) {
35	        if (this.data.rows[i][j] !== other.data.rows[i][j]) return false;
36	      }
37	    }
38	
39	    return true;
40	  }
41	
42	  /**
43	   * Render to DOM element
44	   */
45	  toDOM(): HTMLElement {
46	    const container = document.createElement('div');
47	    container.className = 'cm-table-widget';
48	
49	    const table = document.createElement('table');
50	
51	    // Render header
52	    const thead = document.createElement('thead');
53	    const headerRow = document.createElement('tr');
54	
55	    this.data.headers.forEach((header, idx) => {
56	      const th = document.createElement('th');
57	      th.innerHTML = renderInlineMarkdown(header);
58	      if (this.data.alignments[idx]) {
59	        th.style.textAlign = this.data.alignments[idx]!;
60	      }
61	      headerRow.appendChild(th);
62	    });
63	
64	    thead.appendChild(headerRow);
65	    table.appendChild(thead);
66	
67	    // Render data rows
68	    const tbody = document.createElement('tbody');
69	
70	    this.data.rows.forEach((row) => {
71	      const tr = document.createElement('tr');
72	
73	      row.forEach((cell, idx) => {
74	        const td = document.createElement('td');
75	        td.innerHTML = renderInlineMarkdown(cell);
76	        if (this.data.alignments[idx]) {
77	          td.style.textAlign = this.data.alignments[idx]!;
78	        }
79	        tr.appendChild(td);
80	      });
81	
82	      tbody.appendChild(tr);
83	    });
84	
85	    table.appendChild(tbody);
86	    container.appendChild(table);
87	
88	    return container;
89	  }
90	
91	  /**
92	   * Whether to ignore events
93	   *
94	   * Return false to allow click to enter edit mode
95	   */
96	  ignoreEvent(): boolean {
97	    return false;
98	  }
99	}
100	
101	/**
102	 * Create table widget
103	 */
104	export function createTableWidget(data: TableData): TableWidget {
105	  return new TableWidget(data);
106	}
