1	/**
2	 * Editable Table Widgets
3	 */
4	
5	import { EditorView, WidgetType } from '@codemirror/view';
6	import { TableData } from '../utils/tableParser';
7	import { serializeMarkdownTable } from '../utils/tableSerializer';
8	import { setTableSourceMode } from '../plugins/tableEditorEffects';
9	import { renderInlineMarkdown } from '../utils/inlineMarkdown';
10	
11	function cloneTableData(data: TableData): TableData {
12	  return {
13	    headers: [...data.headers],
14	    alignments: [...data.alignments],
15	    rows: data.rows.map((row) => [...row]),
16	  };
17	}
18	
19	function createEditableCell(
20	  tag: 'th' | 'td',
21	  value: string,
22	  onCommit: (nextValue: string) => void
23	): HTMLTableCellElement {
24	  const cell = document.createElement(tag);
25	  cell.className = 'cm-table-cell';
26	  cell.contentEditable = 'true';
27	  cell.spellcheck = false;
28	  cell.dataset.raw = value;
29	  cell.innerHTML = renderInlineMarkdown(value);
30	
31	  let editing = false;
32	
33	  const commitIfChanged = () => {
34	    const nextValue = cell.textContent ?? '';
35	    const raw = cell.dataset.raw ?? '';
36	    if (nextValue === raw) return;
37	    cell.dataset.raw = nextValue;
38	    onCommit(nextValue);
39	  };
40	
41	  cell.addEventListener('focus', () => {
42	    if (!editing) {
43	      editing = true;
44	      cell.textContent = cell.dataset.raw ?? '';
45	    }
46	  });
47	
48	  cell.addEventListener('blur', (event) => {
49	    event.stopPropagation();
50	    commitIfChanged();
51	    editing = false;
52	    cell.innerHTML = renderInlineMarkdown(cell.dataset.raw ?? '');
53	  });
54	
55	  cell.addEventListener('keydown', (event) => {
56	    if (event.key === 'Enter') {
57	      event.preventDefault();
58	      commitIfChanged();
59	      cell.blur();
60	    }
61	  });
62	
63	  return cell;
64	}
65	
66	export class TableEditorWidget extends WidgetType {
67	  constructor(
68	    readonly data: TableData,
69	    readonly from: number,
70	    readonly to: number
71	  ) {
72	    super();
73	  }
74	
75	  eq(other: TableEditorWidget): boolean {
76	    if (this.data.headers.length !== other.data.headers.length) return false;
77	    if (this.data.rows.length !== other.data.rows.length) return false;
78	
79	    for (let i = 0; i < this.data.headers.length; i++) {
80	      if (this.data.headers[i] !== other.data.headers[i]) return false;
81	      if (this.data.alignments[i] !== other.data.alignments[i]) return false;
82	    }
83	
84	    for (let i = 0; i < this.data.rows.length; i++) {
85	      for (let j = 0; j < this.data.headers.length; j++) {
86	        if (this.data.rows[i][j] !== other.data.rows[i][j]) return false;
87	      }
88	    }
89	
90	    return true;
91	  }
92	
93	  toDOM(view: EditorView): HTMLElement {
94	    const container = document.createElement('div');
95	    container.className = 'cm-table-editor';
96	
97	    const toolbar = document.createElement('div');
98	    toolbar.className = 'cm-table-toolbar';
99	
100	    const toggleButton = document.createElement('button');
101	    toggleButton.type = 'button';
102	    toggleButton.className = 'cm-table-toggle';
103	    toggleButton.textContent = 'MD';
104	    toggleButton.addEventListener('click', (event) => {
105	      event.preventDefault();
106	      event.stopPropagation();
107	      view.dispatch({
108	        selection: { anchor: this.from },
109	        effects: setTableSourceMode.of({
110	          from: this.from,
111	          to: this.to,
112	          showSource: true,
113	        }),
114	      });
115	    });
116	
117	    toolbar.appendChild(toggleButton);
118	    container.appendChild(toolbar);
119	
120	    const table = document.createElement('table');
121	
122	    const commitHeader = (colIndex: number, nextValue: string) => {
123	      const updated = cloneTableData(this.data);
124	      updated.headers[colIndex] = nextValue;
125	      const markdown = serializeMarkdownTable(updated);
126	      view.dispatch({
127	        changes: { from: this.from, to: this.to, insert: markdown },
128	      });
129	    };
130	
131	    const commitCell = (rowIndex: number, colIndex: number, nextValue: string) => {
132	      const updated = cloneTableData(this.data);
133	      updated.rows[rowIndex][colIndex] = nextValue;
134	      const markdown = serializeMarkdownTable(updated);
135	      view.dispatch({
136	        changes: { from: this.from, to: this.to, insert: markdown },
137	      });
138	    };
139	
140	    const thead = document.createElement('thead');
141	    const headerRow = document.createElement('tr');
142	    this.data.headers.forEach((header, idx) => {
143	      const th = createEditableCell('th', header, (nextValue) =>
144	        commitHeader(idx, nextValue)
145	      );
146	      if (this.data.alignments[idx]) {
147	        th.style.textAlign = this.data.alignments[idx]!;
148	      }
149	      headerRow.appendChild(th);
150	    });
151	    thead.appendChild(headerRow);
152	    table.appendChild(thead);
153	
154	    const tbody = document.createElement('tbody');
155	    this.data.rows.forEach((row, rowIndex) => {
156	      const tr = document.createElement('tr');
157	      row.forEach((cellValue, colIndex) => {
158	        const td = createEditableCell('td', cellValue, (nextValue) =>
159	          commitCell(rowIndex, colIndex, nextValue)
160	        );
161	        if (this.data.alignments[colIndex]) {
162	          td.style.textAlign = this.data.alignments[colIndex]!;
163	        }
164	        tr.appendChild(td);
165	      });
166	      tbody.appendChild(tr);
167	    });
168	    table.appendChild(tbody);
169	    container.appendChild(table);
170	
171	    return container;
172	  }
173	
174	  ignoreEvent(): boolean {
175	    return true;
176	  }
177	}
178	
179	export class TableSourceToggleWidget extends WidgetType {
180	  constructor(readonly from: number, readonly to: number) {
181	    super();
182	  }
183	
184	  toDOM(view: EditorView): HTMLElement {
185	    const container = document.createElement('div');
186	    container.className = 'cm-table-source-toggle';
187	
188	    const button = document.createElement('button');
189	    button.type = 'button';
190	    button.className = 'cm-table-toggle';
191	    button.textContent = 'Table';
192	    button.addEventListener('click', (event) => {
193	      event.preventDefault();
194	      event.stopPropagation();
195	      view.dispatch({
196	        effects: setTableSourceMode.of({
197	          from: this.from,
198	          to: this.to,
199	          showSource: false,
200	        }),
201	      });
202	    });
203	
204	    container.appendChild(button);
205	    return container;
206	  }
207	
208	  ignoreEvent(): boolean {
209	    return true;
210	  }
211	}
212	
213	export function createTableEditorWidget(
214	  data: TableData,
215	  from: number,
216	  to: number
217	): TableEditorWidget {
218	  return new TableEditorWidget(data, from, to);
219	}
220	
221	export function createTableSourceToggleWidget(
222	  from: number,
223	  to: number
224	): TableSourceToggleWidget {
225	  return new TableSourceToggleWidget(from, to);
226	}
