1	/**
2	 * Table Parser Utility
3	 *
4	 * Parses Markdown table source into structured data
5	 */
6	
7	/**
8	 * Table data structure
9	 */
10	export interface TableData {
11	  headers: string[];
12	  alignments: ('left' | 'center' | 'right' | null)[];
13	  rows: string[][];
14	}
15	
16	/**
17	 * Parse table row, handling escaped pipes
18	 */
19	function parseRow(line: string): string[] {
20	  // Replace escaped pipes with placeholder first
21	  const placeholder = '\x00PIPE\x00';
22	  const escaped = line.replace(/\\\|/g, placeholder);
23	
24	  // Split by pipe
25	  const cells = escaped.split('|');
26	
27	  // Remove empty cells at start/end (due to |col1|col2| format)
28	  if (cells.length > 0 && cells[0].trim() === '') cells.shift();
29	  if (cells.length > 0 && cells[cells.length - 1].trim() === '') cells.pop();
30	
31	  // Restore placeholder and clean up
32	  return cells.map((cell) =>
33	    cell.replace(new RegExp(placeholder, 'g'), '|').trim()
34	  );
35	}
36	
37	/**
38	 * Parse alignment
39	 */
40	function parseAlignment(cell: string): 'left' | 'center' | 'right' | null {
41	  const trimmed = cell.trim();
42	  const left = trimmed.startsWith(':');
43	  const right = trimmed.endsWith(':');
44	
45	  if (left && right) return 'center';
46	  if (left) return 'left';
47	  if (right) return 'right';
48	  return null;
49	}
50	
51	/**
52	 * Check if row is a separator row
53	 */
54	function isSeparatorRow(cells: string[]): boolean {
55	  if (cells.length === 0) return false;
56	  return cells.every((cell) => /^:?-+:?$/.test(cell.trim()));
57	}
58	
59	/**
60	 * Parse Markdown table
61	 *
62	 * @param source - Table source
63	 * @returns Parsed table data, null for invalid table
64	 */
65	export function parseMarkdownTable(source: string): TableData | null {
66	  const lines = source.split('\n').filter((line) => line.trim() !== '');
67	
68	  if (lines.length < 2) return null;
69	
70	  // Parse header
71	  const headerCells = parseRow(lines[0]);
72	  if (headerCells.length === 0) return null;
73	
74	  // Parse separator row
75	  const separatorCells = parseRow(lines[1]);
76	  if (!isSeparatorRow(separatorCells)) return null;
77	
78	  // Column count must match
79	  if (headerCells.length !== separatorCells.length) return null;
80	
81	  // Parse alignments
82	  const alignments = separatorCells.map(parseAlignment);
83	
84	  // Parse data rows
85	  const rows: string[][] = [];
86	  for (let i = 2; i < lines.length; i++) {
87	    const rowCells = parseRow(lines[i]);
88	    // Pad or truncate to header column count
89	    const normalizedRow = headerCells.map((_, idx) => rowCells[idx] ?? '');
90	    rows.push(normalizedRow);
91	  }
92	
93	  return {
94	    headers: headerCells,
95	    alignments,
96	    rows,
97	  };
98	}
99

1	/**
2	 * Table Serializer Utility
3	 *
4	 * Converts structured table data back to Markdown
5	 */
6	
7	import { TableData } from './tableParser';
8	
9	function escapeCell(value: string): string {
10	  return value.replace(/\|/g, '\\|').replace(/\r?\n/g, ' ').trim();
11	}
12	
13	function alignmentCell(alignment: 'left' | 'center' | 'right' | null): string {
14	  if (alignment === 'left') return ':---';
15	  if (alignment === 'right') return '---:';
16	  if (alignment === 'center') return ':---:';
17	  return '---';
18	}
19	
20	export function serializeMarkdownTable(data: TableData): string {
21	  const headerLine = `| ${data.headers.map(escapeCell).join(' | ')} |`;
22	  const separatorLine = `| ${data.alignments
23	    .map(alignmentCell)
24	    .join(' | ')} |`;
25	  const rowLines = data.rows.map(
26	    (row) => `| ${row.map(escapeCell).join(' | ')} |`
27	  );
28	
29	  return [headerLine, separatorLine, ...rowLines].join('\n');
30	}
